    $ins = $db->prepare(
        "INSERT INTO pet_triggers (trigger_type, trigger_value, animation, bubble_text, effect_happiness, effect_hunger, effect_energy, xp, cooldown_seconds, enabled) "
        . "VALUES ('event', 'gift_sub', 'gift', '', 8, 0, 0, 0, 5, 1)"
    );
    if (!$ins) {
        return false;
    }
    $ok = $ins->execute();
    $ins->close();
    return $ok;
}

function pet_sync_template_animations($db) {
    if (!($db instanceof mysqli) || !pet_table_exists($db, 'pet_animations')) {
        return false;
    }
    $res = $db->query('SELECT name, sprite_file FROM pet_animations');
    if (!($res instanceof mysqli_result)) {
        return false;
    }
    $existing = [];
    $packCounts = [];
    while ($row = $res->fetch_assoc()) {
        $name = (string) ($row['name'] ?? '');
        $existing[$name] = (string) ($row['sprite_file'] ?? '');
        $parsed = pet_parse_template_sprite($row['sprite_file'] ?? '');
        if ($parsed) {
            $packId = $parsed['pack'];
            $packCounts[$packId] = ($packCounts[$packId] ?? 0) + 1;
        }
    }
    $res->free();
    if (!$packCounts) {
        return false;
    }
    arsort($packCounts);
    $packId = (string) array_key_first($packCounts);
    $pack = pet_template_get($packId);
    if (!$pack || empty($pack['animations'])) {
        return false;
    }
    $save = $db->prepare(
        'INSERT INTO pet_animations (name, sprite_file, frame_width, frame_height, frame_count, fps, `loop`) '
        . 'VALUES (?, ?, ?, ?, ?, ?, ?) '
        . 'ON DUPLICATE KEY UPDATE sprite_file = VALUES(sprite_file), frame_width = VALUES(frame_width), '
        . 'frame_height = VALUES(frame_height), frame_count = VALUES(frame_count), fps = VALUES(fps), `loop` = VALUES(`loop`)'
    );
    if (!$save) {
        return false;
    }
    $changed = false;
    foreach ($pack['animations'] as $animName => $spec) {
        $token = pet_template_token($packId, $spec['file']);
        if ($token === '') {
            continue;
        }
        $current = $existing[$animName] ?? '';
        if ($current !== '' && !pet_is_template_sprite($current)) {
            continue;
        }
        if ($current === $token) {
            continue;
        }
        $frameWidth = (int) ($spec['frame_width'] ?? 128);
        $frameHeight = (int) ($spec['frame_height'] ?? 128);
        $frameCount = (int) ($spec['frame_count'] ?? 30);
        $fps = (int) ($spec['fps'] ?? 15);
        $loopFlag = !empty($spec['loop']) ? 1 : 0;
        $save->bind_param('ssiiiii', $animName, $token, $frameWidth, $frameHeight, $frameCount, $fps, $loopFlag);
        if ($save->execute()) {
            $changed = true;
        }
    }
    $save->close();
    return $changed;
}

function pet_clamp_stat($value) {
    $n = (int) round((float) $value);
    if ($n < 0) {
        return 0;
    }
    if ($n > 100) {
        return 100;
    }
    return $n;
}

function pet_stream_is_online($db) {
    if (!($db instanceof mysqli) || !pet_table_exists($db, 'stream_status')) {
        return false;
    }
    $res = $db->query('SELECT status FROM stream_status LIMIT 1');
    if (!$res) {
        return false;
    }
    $row = $res->fetch_assoc();
    $res->free();
    $status = strtolower(trim((string) ($row['status'] ?? '')));
    if (!in_array($status, ['true', '1', 'online'], true)) {
        return false;
    }
    // A Specter VOD rerun replays an old stream, so the pet treats it as offline
    return !pet_rerun_is_live($db);
}

function pet_rerun_is_live($db) {
    try {
        $res = $db->query("SELECT id FROM website.vod_reruns WHERE username = DATABASE() AND status = 'live' LIMIT 1");
        if (!($res instanceof mysqli_result)) {
            return false;
        }
        $live = $res->num_rows > 0;
        $res->free();
        return $live;
    } catch (Throwable $e) {
        return false;
    }
}

function pet_utc_timestamp($value) {
    if ($value === null || $value === '') {
        return null;
    }
    if (is_int($value) || (is_string($value) && ctype_digit($value))) {
        $n = (int) $value;
        if ($n > 1000000000000) {
            $n = (int) floor($n / 1000);
        }
        return $n > 0 ? $n : null;
    }
    $raw = trim((string) $value);
    if ($raw === '') {
        return null;
    }
    $upper = strtoupper($raw);
    if (substr($upper, -1) === 'Z' || strpos($raw, '+') !== false || preg_match('/-\d{2}:\d{2}$/', $raw)) {
        $ts = strtotime($raw);
        return ($ts === false || $ts <= 0) ? null : $ts;
    }
    $dt = DateTimeImmutable::createFromFormat('Y-m-d H:i:s', $raw, new DateTimeZone('UTC'));
    if ($dt instanceof DateTimeImmutable) {
        return $dt->getTimestamp();
    }
    $ts = strtotime($raw . ' UTC');
    return ($ts === false || $ts <= 0) ? null : $ts;
}

function pet_decay_hours($lastAt, $streamOnline = true) {
    if (!$streamOnline) {
        return 0.0;
    }
    $ts = pet_utc_timestamp($lastAt);
    if ($ts === null) {
        return 0.0;
    }
    $hours = (time() - $ts) / 3600.0;
    return $hours < 0 ? 0.0 : $hours;
}

function pet_decayed_stat($stored, $rate, $lastAt, $streamOnline) {
    return pet_clamp_stat((float) $stored - ((float) $rate * pet_decay_hours($lastAt, $streamOnline)));
}

function pet_settings_decay($db) {
    $rates = ['happiness' => 2.0, 'hunger' => 3.0, 'energy' => 1.0];
    $res = $db->query('SELECT decay_happiness, decay_hunger, decay_energy FROM pet_settings WHERE id = 1');
    if ($res && ($row = $res->fetch_assoc())) {
        $rates['happiness'] = (float) ($row['decay_happiness'] ?? 2);
        $rates['hunger'] = (float) ($row['decay_hunger'] ?? 3);
        $rates['energy'] = (float) ($row['decay_energy'] ?? 1);
    }
    return $rates;
}

function pet_state_payload($happiness, $hunger, $energy, $level, $xp, $lastIso, array $rates, $streamOnline = false) {
    return [
        'happiness' => (int) $happiness,
        'hunger' => (int) $hunger,
        'energy' => (int) $energy,
        'level' => (int) $level,
        'xp' => (int) $xp,
        'last_interaction_at' => (string) $lastIso,
        'decay_happiness' => $rates['happiness'],
        'decay_hunger' => $rates['hunger'],
        'decay_energy' => $rates['energy'],
        'decay_rates' => json_encode([
            'happiness' => $rates['happiness'],
            'hunger' => $rates['hunger'],
            'energy' => $rates['energy'],
        ]),
        'stream_online' => $streamOnline ? '1' : '0',
    ];
}

function pet_apply_state_and_notify($db, $apiKey, $effectHappiness, $effectHunger, $effectEnergy, $xpAdd) {
    $rates = pet_settings_decay($db);
    $happiness = 80;
    $hunger = 80;
    $energy = 80;
    $xp = 0;
    $lastAt = null;
    $res = $db->query('SELECT happiness, hunger, energy, xp, last_interaction_at FROM pet_state WHERE id = 1');
    if ($res && ($row = $res->fetch_assoc())) {
        $happiness = $row['happiness'] !== null ? (float) $row['happiness'] : 80;
        $hunger = $row['hunger'] !== null ? (float) $row['hunger'] : 80;
        $energy = $row['energy'] !== null ? (float) $row['energy'] : 80;
        $xp = max(0, (int) ($row['xp'] ?? 0));
        $lastAt = $row['last_interaction_at'];
    }
    $hours = pet_decay_hours($lastAt, pet_stream_is_online($db));
    $happiness = pet_clamp_stat($happiness - $rates['happiness'] * $hours);
    $hunger = pet_clamp_stat($hunger - $rates['hunger'] * $hours);
    $energy = pet_clamp_stat($energy - $rates['energy'] * $hours);
    // A pet already at 100% on every stat earns no XP
    if ($happiness >= 100 && $hunger >= 100 && $energy >= 100) {
        $xpAdd = 0;
    }
    $happiness = pet_clamp_stat($happiness + (int) $effectHappiness);
    $hunger = pet_clamp_stat($hunger + (int) $effectHunger);
    $energy = pet_clamp_stat($energy + (int) $effectEnergy);
    $xp = max(0, $xp + (int) $xpAdd);
    $level = min(99, 1 + intdiv($xp, 100));
    $now = gmdate('Y-m-d H:i:s');
    $nowIso = gmdate('Y-m-d\TH:i:s\Z');
    $stmt = $db->prepare(
        'INSERT INTO pet_state (id, happiness, hunger, energy, level, xp, last_interaction_at) VALUES (1, ?, ?, ?, ?, ?, ?) '
        . 'ON DUPLICATE KEY UPDATE happiness = VALUES(happiness), hunger = VALUES(hunger), energy = VALUES(energy), '
        . 'level = VALUES(level), xp = VALUES(xp), last_interaction_at = VALUES(last_interaction_at)'
    );
    if (!$stmt) {
        return false;
    }
    $stmt->bind_param('iiiiis', $happiness, $hunger, $energy, $level, $xp, $now);
    $ok = $stmt->execute();
    $stmt->close();
    if (!$ok) {
        return false;
    }
    pet_notify_event($apiKey, 'PET_STATE', pet_state_payload($happiness, $hunger, $energy, $level, $xp, $nowIso, $rates, pet_stream_is_online($db)));
    return true;
}

function pet_sprite_url($petMediaUrl, $filename) {
    global $username;
    $url = pet_resolve_sprite_url((string) $username, $filename);
    if ($url !== '') {
        return $url;
    }
    $filename = basename((string) $filename);
    if ($filename === '' || strpos($filename, '..') !== false) {
        return '';
    }
    return $petMediaUrl . rawurlencode($filename);
}

function pet_user_sprite_filename($filename) {
    if (pet_is_template_sprite($filename)) {
        return '';
    }
    $filename = basename((string) $filename);
    if ($filename === '' || strpos($filename, '..') !== false) {
        return '';
    }
    return $filename;
}

function pet_apply_template_pack($db, $packId) {
    $pack = pet_template_get($packId);
    if (!$pack || empty($pack['animations'])) {
        return false;
    }
    $sel = $db->prepare('SELECT sprite_file FROM pet_animations WHERE name = ?');
    $save = $db->prepare(
        'INSERT INTO pet_animations (name, sprite_file, frame_width, frame_height, frame_count, fps, `loop`) '
        . 'VALUES (?, ?, ?, ?, ?, ?, ?) '
        . 'ON DUPLICATE KEY UPDATE sprite_file = VALUES(sprite_file), frame_width = VALUES(frame_width), '
        . 'frame_height = VALUES(frame_height), frame_count = VALUES(frame_count), fps = VALUES(fps), `loop` = VALUES(`loop`)'
    );
    if (!$sel || !$save) {
        if ($sel) {
            $sel->close();
        }
        if ($save) {
            $save->close();
        }
        return false;
    }
    $toUnlink = [];
    foreach ($pack['animations'] as $animName => $spec) {
        $token = pet_template_token($packId, $spec['file']);
        if ($token === '') {
            $sel->close();
            $save->close();
            return false;
        }
        $sel->bind_param('s', $animName);
        if ($sel->execute()) {
            $res = $sel->get_result();
            $row = $res ? $res->fetch_assoc() : null;
            if ($res) {
                $res->free();
            }
            if ($row) {
                $oldFilename = pet_user_sprite_filename($row['sprite_file'] ?? '');
                if ($oldFilename !== '') {
                    $toUnlink[] = $oldFilename;
                }
            }
        }
        $frameWidth = (int) ($spec['frame_width'] ?? 128);
        $frameHeight = (int) ($spec['frame_height'] ?? 128);
        $frameCount = (int) ($spec['frame_count'] ?? 30);
        $fps = (int) ($spec['fps'] ?? 15);
        $loopFlag = !empty($spec['loop']) ? 1 : 0;
        $save->bind_param('ssiiiii', $animName, $token, $frameWidth, $frameHeight, $frameCount, $fps, $loopFlag);
        if (!$save->execute()) {
            $sel->close();
            $save->close();
            return false;
        }
    }
    $sel->close();
    $save->close();
    // Drop starter animations the new pack doesn't have (switching from Dog left its bark/bite playing on the new pet)
    $staleRes = $db->query("SELECT id, name FROM pet_animations WHERE sprite_file LIKE 'template:%'");
    if ($staleRes) {
        $staleDel = $db->prepare('DELETE FROM pet_animations WHERE id = ?');
        while ($staleRow = $staleRes->fetch_assoc()) {
            if ($staleDel && !isset($pack['animations'][(string) $staleRow['name']])) {
                $staleId = (int) $staleRow['id'];
                $staleDel->bind_param('i', $staleId);
                $staleDel->execute();
            }
        }
        $staleRes->free();
        if ($staleDel) {
            $staleDel->close();
        }
    }
    $idle = 'idle';
    $idleStmt = $db->prepare(
        'INSERT INTO pet_settings (id, idle_animation) VALUES (1, ?) ON DUPLICATE KEY UPDATE idle_animation = VALUES(idle_animation)'
    );
    if ($idleStmt) {
        $idleStmt->bind_param('s', $idle);
        $idleStmt->execute();
        $idleStmt->close();
    }
    return $toUnlink;
}

function pet_unlink_if_unused($db, $petMediaDir, $filename) {
    $filename = basename((string) $filename);
    if ($filename === '' || strpos($filename, '..') !== false) {
        return;
    }
    $stmt = $db->prepare('SELECT COUNT(*) AS c FROM pet_animations WHERE sprite_file = ?');
    if (!$stmt) {
        return;
    }
    $stmt->bind_param('s', $filename);
    $stmt->execute();
    $res = $stmt->get_result();
    $row = $res ? $res->fetch_assoc() : null;
    $stmt->close();
    if ($row && (int) $row['c'] > 0) {
        return;
    }
    $path = rtrim($petMediaDir, '/\\') . '/' . $filename;
    if (is_file($path)) {
        @unlink($path);
    }
}

