    if ($action === 'save_schedule') {
        if (!pet_ensure_schedules_table($db)) {
            pet_json_exit(['success' => false, 'error' => t('pet_save_error')]);
        }
        $schedId = (int) ($_POST['id'] ?? 0);
        $message = trim((string) ($_POST['message'] ?? ''));
        $message = preg_replace('/\s+/u', ' ', $message);
        if ($message === '') {
            pet_json_exit(['success' => false, 'error' => t('pet_schedule_error_empty')]);
        }
        if (mb_strlen($message) > PET_SCHEDULE_MSG_MAX) {
            $message = mb_substr($message, 0, PET_SCHEDULE_MSG_MAX);
        }
        $animation = pet_sanitize_anim_name($_POST['animation'] ?? 'happy');
        if ($animation === '') {
            $animation = 'happy';
        }
        $interval = (int) ($_POST['interval_minutes'] ?? 15);
        if ($interval < PET_SCHEDULE_MIN_MINUTES) {
            $interval = PET_SCHEDULE_MIN_MINUTES;
        }
        if ($interval > PET_SCHEDULE_MAX_MINUTES) {
            $interval = PET_SCHEDULE_MAX_MINUTES;
        }
        $enabled = ((int) ($_POST['enabled'] ?? 1)) === 1 ? 1 : 0;
        if ($schedId <= 0) {
            $countRes = $db->query('SELECT COUNT(*) AS c FROM pet_schedules');
            $countRow = $countRes ? $countRes->fetch_assoc() : null;
            if ($countRow && (int) $countRow['c'] >= PET_SCHEDULE_MAX_ROWS) {
                pet_json_exit(['success' => false, 'error' => t('pet_schedule_error_limit')]);
            }
            $ins = $db->prepare(
                'INSERT INTO pet_schedules (message, animation, interval_minutes, enabled) VALUES (?, ?, ?, ?)'
            );
            if (!$ins) {
                pet_json_exit(['success' => false, 'error' => t('pet_save_error')]);
            }
            $ins->bind_param('ssii', $message, $animation, $interval, $enabled);
            if (!$ins->execute()) {
                $ins->close();
                pet_json_exit(['success' => false, 'error' => t('pet_save_error')]);
            }
            $ins->close();
        } else {
            $up = $db->prepare(
                'UPDATE pet_schedules SET message = ?, animation = ?, interval_minutes = ?, enabled = ? WHERE id = ?'
            );
            if (!$up) {
                pet_json_exit(['success' => false, 'error' => t('pet_save_error')]);
            }
            $up->bind_param('ssiii', $message, $animation, $interval, $enabled, $schedId);
            if (!$up->execute()) {
                $up->close();
                pet_json_exit(['success' => false, 'error' => t('pet_save_error')]);
            }
            $up->close();
        }
        pet_notify_event($petNotifyApiKey, 'PET_SETTINGS_UPDATE');
        pet_json_exit(['success' => true, 'message' => t('pet_saved')]);
    }

    if ($action === 'delete_schedule') {
        if (!pet_ensure_schedules_table($db)) {
            pet_json_exit(['success' => false, 'error' => t('pet_save_error')]);
        }
        $schedId = (int) ($_POST['id'] ?? 0);
        if ($schedId <= 0) {
            pet_json_exit(['success' => false, 'error' => t('pet_save_error')]);
        }
        $del = $db->prepare('DELETE FROM pet_schedules WHERE id = ?');
        if (!$del) {
            pet_json_exit(['success' => false, 'error' => t('pet_save_error')]);
        }
        $del->bind_param('i', $schedId);
        if (!$del->execute()) {
            $del->close();
            pet_json_exit(['success' => false, 'error' => t('pet_save_error')]);
        }
        $del->close();
        pet_notify_event($petNotifyApiKey, 'PET_SETTINGS_UPDATE');
        pet_json_exit(['success' => true]);
    }

    pet_json_exit(['success' => false, 'error' => t('pet_save_error')]);
}

header('Content-Type: application/json');
header('Cache-Control: no-store');
if (($_GET['beta'] ?? '') === 'url') {
    if ((string) $api_key === '') beta_pet_fail('Your account has no channel key yet.', 409);
    echo json_encode(['success' => true, 'url' => $overlayLinkWithCode]); exit();
}
$bPacks = [];
foreach ($petTemplateCatalog as $packId => $pack) {
    $an = [];
    foreach ($pack['animations'] as $animName => $spec) $an[] = ['name' => (string) $animName, 'sheet' => pet_template_cdn_url($packId, $spec['file']), 'frames' => (int) $spec['frame_count'], 'fps' => (int) $spec['fps']];
    $th = [];
    foreach (($pack['themes'] ?? []) as $themeId => $themeKey) $th[] = ['id' => (string) $themeId, 'label' => t($themeKey)];
    $bPacks[] = ['id' => (string) $packId, 'base' => pet_template_base_id($pack), 'category' => (string) ($pack['category'] ?? 'animals'), 'themes' => $th,
        'name' => t($pack['name_key']), 'desc' => t($pack['desc_key']), 'static' => pet_template_cdn_url($packId, $pack['preview'] ?? 'static.png'), 'anims' => $an];
}
$bCats = [];
foreach (pet_template_categories() as $id => $key) $bCats[] = ['id' => $id, 'label' => t($key)];
foreach (['scale', 'decay_happiness', 'decay_hunger', 'decay_energy'] as $k) $pet[$k] = (float) $pet[$k];
foreach (['start_happiness', 'start_hunger', 'start_energy', 'alert_threshold', 'alert_cooldown_minutes'] as $k) $pet[$k] = (int) $pet[$k];
$pet['visible_stats'] = $visibleStats;
$bOut = json_encode(['success' => true, 'has_key' => (string) $api_key !== '', 'settings' => $pet, 'alert_defaults' => $petAlertDefaults,
    'state' => ['stream_online' => $petStreamOnline ? 1 : 0, 'happiness' => (int) $petState['happiness'], 'hunger' => (int) $petState['hunger'], 'energy' => (int) $petState['energy'], 'xp' => $petLiveXp, 'last_interaction_at' => $petLastUnix],
    'animations' => $petAnimations, 'anim_names' => $petAnimNameList, 'triggers' => $petTriggers, 'schedules' => $petSchedules, 'rewards' => $petRewards,
    'packs' => $bPacks, 'categories' => $bCats, 'active_template' => $petActiveTemplate,
    'limits' => ['min_px' => PET_IMAGE_MIN_PX, 'max_px' => PET_IMAGE_MAX_PX, 'max_bytes' => PET_IMAGE_MAX_BYTES, 'frames' => PET_FRAME_COUNT_MAX, 'msg' => PET_SCHEDULE_MSG_MAX, 'min_min' => PET_SCHEDULE_MIN_MINUTES, 'max_min' => PET_SCHEDULE_MAX_MINUTES, 'rows' => PET_SCHEDULE_MAX_ROWS]], JSON_UNESCAPED_UNICODE);
// No em-dashes in beta copy: the live lang strings use them as separators.
echo str_replace("\u{2014}", ',', str_replace(" \u{2014} ", ', ', $bOut));
exit();
